package net.officefloor.hq.app;

import java.util.regex.Pattern;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/clients} — add a client (name + email) and return the created row. Wired by
 * {@code officefloor/rest/api/clients.POST.yml}. The create is audited through {@link Audit}.
 */
public class ClientsPost {

    // Every client must carry a proper email. Mirror of the UI check (ClientsPage.isValidEmail) so a
    // request that bypasses the form is still rejected before any row or audit record is written.
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    public void service(@RequestBody NewClient body, ClientRepository repository, Audit audit,
            ObjectResponse<Client> response) {
        String email = body.getEmail() == null ? "" : body.getEmail().trim();
        if (!EMAIL.matcher(email).matches()) {
            throw new IllegalArgumentException("a client requires a valid email address");
        }
        Client client = new Client();
        client.setName(body.getName());
        client.setEmail(body.getEmail());
        Client saved = repository.save(client);
        audit.record("CLIENT_CREATED id=" + saved.getId() + " name=" + saved.getName());
        response.send(saved);
    }
}
package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Data access for {@link Client}. A Spring Data bean, injected into the OfficeFloor logic classes
 * that back the /api/clients routes.
 */
public interface ClientRepository extends JpaRepository<Client, Long> {

    /** All clients, oldest first, so the list order is stable for the UI and tests. */
    List<Client> findAllByOrderByIdAsc();

    /**
     * Clients whose name contains {@code term} (case-insensitive), oldest first. Backs the
     * name search box on the clients page ({@code GET /api/clients?q=...}).
     */
    List<Client> findByNameContainingIgnoreCaseOrderByIdAsc(String term);

    /**
     * Non-archived clients only, oldest first — the default clients list. Archived clients are kept
     * but tucked away, so they drop off this list.
     */
    List<Client> findByArchivedFalseOrderByIdAsc();

    /**
     * Non-archived clients whose name contains {@code term} (case-insensitive), oldest first — the
     * name search, which likewise excludes archived clients.
     */
    List<Client> findByArchivedFalseAndNameContainingIgnoreCaseOrderByIdAsc(String term);
}
package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A client the user tracks: a name and an email. Mapped to the {@code client} table created by
 * {@code V1__clients.sql}. IDENTITY id so the DB assigns it on insert (seed inserts explicit ids
 * via JdbcTemplate; GENERATED BY DEFAULT allows both).
 */
@Entity
@Table(name = "client")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    /** Archived clients are kept but hidden from the default list and search (V19__client_archived.sql). */
    @Column(nullable = false)
    private boolean archived;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }
}

